// Reference input for the S6-41 encoder forms. Assembled locally with Apple
// clang for arm64-apple-macosx15.0 -march=armv8.4-a and read back with
// `otool -tV`; expected words are in the encoder tests.
.text
.globl _fx
_fx:
    ldrb w9, [x22]
    ldrh w9, [x22, #2]
    ldr w9, [x22, #4]
    ldr x9, [x22, #8]
    ldr xzr, [x22]
    strb w9, [x22, #1]
    strh w9, [x22, #2]
    str w9, [x22, #4]
    str x9, [x22, #8]
    str wzr, [x22]
    ldarb w9, [x22]
    ldarh w9, [x22]
    ldar w9, [x22]
    ldar x9, [x22]
    stlrb w9, [x22]
    stlrh w9, [x22]
    stlr w9, [x22]
    stlr x9, [x22]
    stlr xzr, [sp]
    ldaddb w10, w11, [x12]
    ldaddh w10, w11, [x12]
    ldadd w10, w11, [x12]
    ldadd x10, x11, [x12]
    ldaddalb w10, w11, [x12]
    ldaddalh w10, w11, [x12]
    ldaddal w10, w11, [x12]
    ldaddal x10, x11, [x12]
    ldaddal xzr, x11, [sp]
    swpb w10, w11, [x12]
    swph w10, w11, [x12]
    swp w10, w11, [x12]
    swp x10, x11, [x12]
    swpalb w10, w11, [x12]
    swpalh w10, w11, [x12]
    swpal w10, w11, [x12]
    swpal x10, x11, [x12]
    casb w10, w11, [x12]
    cash w10, w11, [x12]
    cas w10, w11, [x12]
    cas x10, x11, [x12]
    casalb w10, w11, [x12]
    casalh w10, w11, [x12]
    casal w10, w11, [x12]
    casal x10, x11, [x12]
    casal x10, xzr, [x12]
    dmb ish
    dmb ishld
